const MediaTile4_data = [
    { id: "w-node-_0dae8f7a-551d-3e4a-b521-d1a5100e0357-1a518a83", description: "\"Für uns bedeutet AI eine neue Art zu arbeiten. Die DECAID Academy hilft uns dabei, AI-Technologien sinnvoll in unsere Geschäftsfelder einzubinden – von der Strategie über Kampagnen- und Contenterstellung bis zu Performance und Analytics. Unsere Agentur wird spürbar leistungsfähiger\"", imgSrc: "/assets/cloned/images/023e989528e1.jpeg", text: "Stephan Tiersch", text2: "Geschäftsführer bei Kresse & Discher" },
    { id: "w-node-_1198969b-9674-1869-838a-89526779ea6d-1a518a83", description: "\"AI ist ein entscheidender Faktor für die Zukunft der Markenkommunikation – und mit der DECAID Academy haben wir einen Partner gefunden, der uns auf diesem Weg begleitet. Die klar strukturierten Inhalte und praxisnahen Anwendungsfälle machen es einfach, AI effizient in unseren Arbeitsalltag zu integrieren.\"", imgSrc: "/assets/cloned/images/bb6f52242d63.jpeg", text: "Kai-Uwe Lehanka", text2: "Geschäftsführer bei Lehanka Kommunikationsagentur" },
    { id: "w-node-f7d846ec-3cd1-5c81-d986-01ec8aa8b8ac-1a518a83", description: "\"Auf unserer Generative AI Transformations-Journey haben wir mit der DECAID Academy einen überzeugenden Partner gefunden. Kontinuierliche Begleitung, praxisbezogene Schulungen und regelmäßige Updates helfen uns an den richtigen Stellen, Gen AI effektiv in unsere Wertschöpfungsprozesse einzubinden. So bringt Veränderung Erfolg und macht auch noch Spaß.\"", imgSrc: "/assets/cloned/images/c95eeb0b45f2.jpeg", text: "Thomas Göring", text2: "Geschäftsführer marmato GmbH" },
    { id: "w-node-_0905dfb2-022f-46ea-6572-d09d1c664f0d-1a518a83", description: "\"Nach mehreren Kursen an der DECAID Academy bin ich bereit, AI-Tools in meinem Arbeitsalltag einzusetzen. Die Dozenten sind äußerst kompetent und die Kurse praxisnah. Eine einzigartige Lernerfahrung!\"", imgSrc: "/assets/cloned/images/a713988c8093.png", text: "David Lux", text2: "Inhaber bei Evertouch" }
];
